    'SHS 1: Laboratory safety, apparatus and separation techniques' => [
        ['The apparatus used to measure a fixed volume of solution accurately, such as 25.0 cm³, is a', ['pipette', 'beaker', 'conical flask', 'measuring cylinder'], 'A', 'A pipette delivers one fixed volume accurately.', 2],
        ['A burette is used to', ['heat solids strongly', 'deliver variable volumes of a solution accurately during a titration', 'store gases', 'grind solids'], 'B', 'It is read to 0.05 cm³.', 2],
        ['A substance labelled with a skull and crossbones symbol is', ['flammable', 'corrosive', 'toxic', 'radioactive'], 'C', 'Poisonous if swallowed, inhaled or absorbed.', 1],
        ['The hazard symbol showing a flame means the substance is', ['toxic', 'an irritant', 'explosive', 'flammable'], 'D', 'It catches fire easily.', 1],
        ['When diluting a concentrated acid, you should', ['add the acid slowly to water', 'add water quickly to the acid', 'heat the acid first', 'shake the acid in a closed bottle'], 'A', 'Adding water to acid can boil and spit.', 3],
