    'SHS 1: Periodic table: groups, periods and blocks' => [
        ['The modern periodic table arranges elements in order of increasing', ['atomic number', 'mass number', 'density', 'number of neutrons'], 'A', 'Moseley\'s work.', 1],
        ['Elements in the same group have the same', ['number of shells', 'number of valence electrons', 'mass number', 'number of neutrons'], 'B', 'So they react similarly.', 1],
        ['Elements in the same period have the same', ['number of valence electrons', 'chemical properties', 'number of occupied electron shells', 'atomic mass'], 'C', 'Across a row.', 1],
        ['Group 18 elements are called', ['halogens', 'alkali metals', 'alkaline earth metals', 'noble gases'], 'D', 'They have full outer shells.', 1],
        ['Group 1 elements are called', ['alkali metals', 'halogens', 'noble gases', 'transition metals'], 'A', 'They form alkaline hydroxides.', 1],
        ['Group 2 elements are called', ['alkali metals', 'alkaline earth metals', 'halogens', 'chalcogens'], 'B', 'Be, Mg, Ca, Sr, Ba.', 1],
        ['Elements whose outermost electron enters a d subshell belong to the', ['s-block', 'p-block', 'd-block (transition elements)', 'f-block'], 'C', 'Groups 3 to 12.', 2],
        ['Down a group, ionisation energy generally', ['increases', 'stays the same', 'becomes zero', 'decreases'], 'D', 'Outer electrons are further from the nucleus and better shielded.', 3],
        ['Electronegativity is', ['the ability of an atom in a bond to attract the shared electrons', 'the energy released when an atom gains an electron', 'the size of an atom', 'the charge on the nucleus'], 'A', 'Fluorine is the most electronegative.', 3],
        ['Metallic character across a period', ['increases', 'decreases', 'is unchanged', 'first rises then disappears'], 'B', 'Na is metallic; Cl is a non-metal.', 3],
        ['An element with configuration 2, 8, 7 is in group', ['7', '3', '17', '1'], 'C', 'Seven valence electrons: group 17.', 2],
        ['In which period of the periodic table is neon (Z = 10)?', ['18', '3', '1', '2'], 'D', 'Number of occupied shells.', 2],
        ['In which group of the periodic table is silicon (Z = 14)?', ['14', '3', '13', '15'], 'A', 'From its valence electrons.', 2],
        ['In which group of the periodic table is sulphur (Z = 16)?', ['3', '16', '15', '17'], 'B', 'From its valence electrons.', 2],
        ['In which period of the periodic table is silicon (Z = 14)?', ['14', '4', '3', '2'], 'C', 'Number of occupied shells.', 2],
        ['In which period of the periodic table is beryllium (Z = 4)?', ['3', '1', '4', '2'], 'D', 'Number of occupied shells.', 2],
        ['In which period of the periodic table is magnesium (Z = 12)?', ['3', '2', '4', '5'], 'A', 'Number of occupied shells.', 2],
        ['In which group of the periodic table is magnesium (Z = 12)?', ['3', '2', '1', '12'], 'B', 'From its valence electrons.', 2],
        ['Elements in the same group have similar chemical properties.', ['True', 'False'], 'A', 'Same number of valence electrons.', 1, 'tf'],
        ['Atomic radius increases down a group.', ['True', 'False'], 'A', 'More shells.', 2, 'tf'],
        ['First ionisation energy generally increases across a period.', ['True', 'False'], 'A', 'Increasing nuclear charge.', 3, 'tf'],
