        ['The temperature of 50 g of water rises by 8 °C. How much heat was absorbed? (c = 4.2 J g⁻¹ °C⁻¹)', ['1,680 J', '400 J', '210 J', '1.68 J'], 'A', 'q = mcΔT = 50 × 4.2 × 8.', 2],
        ['Given A → B, ΔH₁ = −286 kJ, and B → C, ΔH₂ = −572 kJ, find ΔH for A → C.', ['286 kJ', '−858 kJ', '−286 kJ', '858 kJ'], 'B', 'Hess\'s law: ΔH = ΔH₁ + ΔH₂.', 3],
        ['Given A → B, ΔH₁ = −286 kJ, and B → C, ΔH₂ = −890 kJ, find ΔH for A → C.', ['604 kJ', '−604 kJ', '−1,176 kJ', '1,176 kJ'], 'C', 'Hess\'s law: ΔH = ΔH₁ + ΔH₂.', 3],
        ['A neutralisation releases 1.425 kJ when 0.025 mol of water is formed. Calculate the enthalpy of neutralisation.', ['+57 kJ/mol', '−0.036 kJ/mol', '−1.425 kJ/mol', '−57 kJ/mol'], 'D', 'ΔH = −q ÷ n = −1.425 ÷ 0.025.', 4],
        ['A neutralisation releases 2.85 kJ when 0.05 mol of water is formed. Calculate the enthalpy of neutralisation.', ['−57 kJ/mol', '+57 kJ/mol', '−0.143 kJ/mol', '−2.85 kJ/mol'], 'A', 'ΔH = −q ÷ n = −2.85 ÷ 0.05.', 4],
