        ['Every Brønsted–Lowry acid has a conjugate base.', ['True', 'False'], 'A', 'Formed after losing a proton.', 3, 'tf'],
        ['The conjugate base of H₂O is ___.', ['OH⁻', 'OH-', 'hydroxide', 'hydroxide ion'], '', 'Water loses a proton.', 3, 'fill'],
        ['The conjugate acid of H₂O is ___.', ['H₃O⁺', 'H3O+', 'hydroxonium', 'hydronium', 'hydroxonium ion', 'oxonium ion'], '', 'Water gains a proton.', 3, 'fill'],
        ['An oxide that reacts with both acids and alkalis is described as ___.', ['amphoteric'], '', 'For example ZnO.', 2, 'fill'],
