        ['All nitrates are', ['insoluble in water', 'soluble in water', 'coloured', 'acidic'], 'B', 'A solubility rule.', 1],
        ['Which carbonates are soluble in water?', ['calcium and barium carbonates', 'copper and iron carbonates', 'sodium, potassium and ammonium carbonates', 'all carbonates'], 'C', 'Others are insoluble.', 2],
        ['A gas that turns lime water milky is', ['oxygen', 'hydrogen', 'ammonia', 'carbon dioxide'], 'D', 'CaCO₃ precipitate forms.', 1],
