        ['The general formula of the alkanoic acids is', ['CₙH₂ₙ₊₁OH', 'CₙH₂ₙ₊₁COOH', 'CₙH₂ₙ', 'CₙH₂ₙ₊₂'], 'B', 'Alkyl group + COOH.', 2],
        ['Ethanoic acid is a strong acid.', ['True', 'False'], 'B', 'It is a weak acid that ionises partially.', 1, 'tf'],
        ['Fermentation produces carbon dioxide.', ['True', 'False'], 'A', 'Glucose → ethanol + carbon dioxide.', 1, 'tf'],
