        ['Esterification is a reversible reaction.', ['True', 'False'], 'A', 'It reaches equilibrium.', 3, 'tf'],
        ['Ethanol turns acidified potassium dichromate from green to orange.', ['True', 'False'], 'B', 'It turns orange dichromate green.', 3, 'tf'],
        ['Ethanol is used as a solvent and a fuel.', ['True', 'False'], 'A', 'For example in perfumes and gasohol.', 1, 'tf'],
        ['The enzyme in yeast that converts glucose to ethanol is ___.', ['zymase'], '', 'Fermentation.', 3, 'fill'],
        ['The reaction between an alkanoic acid and an alkanol to form an ester is called ___.', ['esterification'], '', 'Catalysed by conc. H₂SO₄.', 2, 'fill'],
        ['The functional group of the alkanoic acids, –COOH, is called the ___ group.', ['carboxyl', 'carboxylic', 'carboxylic acid'], '', 'C=O and –OH together.', 2, 'fill'],
