    'SHS 3: pH, Ka and buffer solutions' => [
        ['pH is defined as', ['−log₁₀[H⁺]', 'log₁₀[H⁺]', '[H⁺] × 10', '−log₁₀[OH⁻] always'], 'A', 'The negative logarithm of hydrogen ion concentration.', 3],
        ['At 25 °C, the ionic product of water, Kw, is', ['1.0 × 10⁻⁷ mol² dm⁻⁶', '1.0 × 10⁻¹⁴ mol² dm⁻⁶', '14 mol² dm⁻⁶', '7.0 mol² dm⁻⁶'], 'B', '[H⁺][OH⁻].', 4],
        ['At 25 °C, pH + pOH =', ['7', '0', '14', '1'], 'C', 'From Kw.', 3],
        ['A buffer solution is one that', ['has pH 7 always', 'is very concentrated', 'changes pH quickly', 'resists changes in pH when small amounts of acid or alkali are added'], 'D', 'For example ethanoic acid and sodium ethanoate.', 3],
        ['An acidic buffer can be made from', ['a weak acid and its salt with a strong base', 'a strong acid and a strong base', 'a strong acid and its salt', 'water and salt'], 'A', 'CH₃COOH + CH₃COONa.', 4],
        ['A basic buffer can be made from', ['a strong base alone', 'a weak base and its salt with a strong acid', 'a strong acid and water', 'a weak acid alone'], 'B', 'NH₃ + NH₄Cl.', 4],
        ['Blood is kept at a pH of about 7.4 by', ['drinking water', 'stomach acid', 'buffer systems such as H₂CO₃/HCO₃⁻', 'salt'], 'C', 'A natural buffer.', 3],
        ['The acid dissociation constant, Ka, for HA ⇌ H⁺ + A⁻ is', ['[HA] / ([H⁺][A⁻])', '[H⁺] + [A⁻]', '[HA][H⁺]', '[H⁺][A⁻] / [HA]'], 'D', 'Larger Ka means a stronger acid.', 4],
        ['pKa is', ['−log₁₀ Ka', 'log₁₀ Ka', 'Ka × 14', '1 ÷ Ka'], 'A', 'A smaller pKa means a stronger acid.', 4],
        ['A solution with pH 3 has a hydrogen ion concentration', ['10 times smaller than one with pH 4', '10 times greater than one with pH 4', 'equal to one with pH 4', '3 times greater than pH 1'], 'B', 'Each pH unit is a factor of 10.', 3],
        ['Calculate the pH of 1 × 10⁻³ mol/dm³ sodium hydroxide solution at 25 °C.', ['3', '10', '11', '12'], 'C', 'pOH = 3; pH = 14 − 3.', 4],
        ['Calculate the pH of a solution with [H⁺] = 5 × 10⁻² mol/dm³.', ['12.7', '−1.3', '2.3', '1.3'], 'D', 'pH = −log₁₀(5 × 10⁻²).', 3],
        ['Calculate the pH of a solution with [H⁺] = 2 × 10⁻² mol/dm³.', ['1.7', '12.3', '−1.7', '2.7'], 'A', 'pH = −log₁₀(2 × 10⁻²).', 3],
        ['Calculate the pH of a solution with [H⁺] = 10⁻¹ mol/dm³.', ['13', '1', '−1', '2'], 'B', 'pH = −log₁₀(10⁻¹).', 3],
        ['A weak acid has Ka = 1 × 10⁻⁵ mol/dm³. Find the pH of a 0.01 mol/dm³ solution.', ['2', '5', '3.5', '7'], 'C', '[H⁺] = √(Ka × c) = 3.16 × 10⁻⁴.', 5],
        ['A weak acid has Ka = 1 × 10⁻⁵ mol/dm³. Find the pH of a 0.4 mol/dm³ solution.', ['0.4', '5', '5.4', '2.7'], 'D', '[H⁺] = √(Ka × c) = 2 × 10⁻³.', 5],
        ['Calculate the pH of 1 × 10⁻⁴ mol/dm³ sodium hydroxide solution at 25 °C.', ['10', '4', '11', '9'], 'A', 'pOH = 4; pH = 14 − 4.', 4],
        ['Calculate the pH of a solution with [H⁺] = 10⁻³ mol/dm³.', ['11', '3', '−3', '4'], 'B', 'pH = −log₁₀(10⁻³).', 3],
        ['A weak acid has Ka = 6.4 × 10⁻⁵ mol/dm³. Find the pH of a 0.4 mol/dm³ solution.', ['0.4', '4.19', '2.3', '4.59'], 'C', '[H⁺] = √(Ka × c) = 5.06 × 10⁻³.', 5],
        ['A weak acid has Ka = 1.8 × 10⁻⁵ mol/dm³. Find the pH of a 0.1 mol/dm³ solution.', ['1', '4.74', '5.74', '2.87'], 'D', '[H⁺] = √(Ka × c) = 1.34 × 10⁻³.', 5],
        ['A solution of pH 2 is more acidic than one of pH 5.', ['True', 'False'], 'A', 'Lower pH, more H⁺.', 1, 'tf'],
        ['Pure water at 25 °C has pH 7.', ['True', 'False'], 'A', '[H⁺] = 10⁻⁷ mol/dm³.', 2, 'tf'],
        ['Adding water to a buffer solution changes its pH greatly.', ['True', 'False'], 'B', 'The ratio of acid to salt is unchanged.', 4, 'tf'],
        ['A strong acid has a large Ka value.', ['True', 'False'], 'A', 'It ionises almost completely.', 3, 'tf'],
        ['The pH of 0.01 mol/dm³ HCl is 1.', ['True', 'False'], 'B', 'pH = −log 0.01 = 2.', 3, 'tf'],
        ['Universal indicator turns purple in strongly alkaline solutions.', ['True', 'False'], 'A', 'pH 12 to 14.', 1, 'tf'],
        ['The pH of a solution with [H⁺] = 10⁻⁶ mol/dm³ is ___.', ['6'], '', 'pH = −log 10⁻⁶.', 2, 'fill'],
        ['The pH of a solution with [H⁺] = 10⁻¹ mol/dm³ is ___.', ['1'], '', 'pH = −log 10⁻¹.', 2, 'fill'],
        ['The pH of a solution with [H⁺] = 10⁻³ mol/dm³ is ___.', ['3'], '', 'pH = −log 10⁻³.', 2, 'fill'],
